class BowlingGame:
    def __init__(self):
        self._rolls = []
        self._frame = 0
        self._frame_pins = 0
        self._rolls_in_frame = 0

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception("Roll must knock down between 0 and 10 pins")
        if self._frame >= 10:
            raise Exception("Cannot roll after the game has ended")

        if self._frame < 9:
            if self._frame_pins + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 pins")
            self._rolls.append(pins)
            self._frame_pins += pins
            self._rolls_in_frame += 1
            if self._frame_pins == 10 or self._rolls_in_frame == 2:
                self._advance_frame()
        else:
            self._validate_tenth_frame(pins)
            self._rolls.append(pins)
            self._frame_pins += pins
            self._rolls_in_frame += 1
            if self._tenth_frame_over():
                self._frame = 10

    def _advance_frame(self):
        self._frame += 1
        self._frame_pins = 0
        self._rolls_in_frame = 0

    def _validate_tenth_frame(self, pins):
        if self._rolls_in_frame == 1:
            first = self._rolls[-1]
            if first != 10 and first + pins > 10:
                raise Exception("Two rolls in the tenth frame cannot score more than 10 pins")
        elif self._rolls_in_frame == 2:
            first = self._rolls[-2]
            second = self._rolls[-1]
            if first == 10 and second != 10 and second + pins > 10:
                raise Exception("Bonus rolls in the tenth frame cannot score more than 10 pins")

    def _tenth_frame_over(self):
        if self._rolls_in_frame < 2:
            return False
        first = self._rolls[-self._rolls_in_frame]
        if first == 10:
            return self._rolls_in_frame == 3
        return self._frame_pins != 10

    def score(self):
        if self._frame < 10:
            raise Exception("Cannot score an incomplete game")
        total = 0
        i = 0
        for frame in range(10):
            if frame < 9:
                if self._rolls[i] == 10:
                    total += 10 + self._rolls[i + 1] + self._rolls[i + 2]
                    i += 1
                elif self._rolls[i] + self._rolls[i + 1] == 10:
                    total += 10 + self._rolls[i + 2]
                    i += 2
                else:
                    total += self._rolls[i] + self._rolls[i + 1]
                    i += 2
            else:
                total += sum(self._rolls[i:])
        return total

